#!/usr/bin/env bash
# AUTO-GENERATED by generate_configs.py — regenerate, don't hand-edit.
# HP combo none_ck128_lr0p00025 — runs all cells (GRU RetNet GatedDeltaNet) in PARALLEL on ONE GPU, 1 seed
# each. Knobs: PYTHON DEVICE RUNS_DIR SEED EXTRA.
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$HERE/../../.." && pwd)"
cd "$REPO_ROOT"
if [[ -z "${PYTHON:-}" ]]; then
  if [[ -x ".venv/bin/python" ]]; then PYTHON=".venv/bin/python"; else PYTHON="python"; fi
fi
DEVICE="${DEVICE:-cuda}"; RUNS_DIR="${RUNS_DIR:-runs/mysterypath_hpsweep}"
SEED="${SEED:-0}"; EXTRA="${EXTRA:-}"
LOGDIR="$HERE/../_logs"; mkdir -p "$LOGDIR"
CELLS="GRU RetNet GatedDeltaNet"; COMBO="none_ck128_lr0p00025"
echo "[$COMBO] cells=[$CELLS] seed=$SEED device=$DEVICE (cells parallel on one GPU)"
pids=()
for cell in $CELLS; do
  CFG="$HERE/../configs/mpg_hp_${cell}_${COMBO}.yaml"
  "$PYTHON" -m train --config "$CFG" --seed "$SEED" \
      --runs-dir "$RUNS_DIR" --device "$DEVICE" $EXTRA \
      > "$LOGDIR/${cell}_${COMBO}_seed${SEED}.log" 2>&1 &
  pids+=("$!")
  echo "  launched $cell (pid $!) -> $LOGDIR/${cell}_${COMBO}_seed${SEED}.log"
done
fail=0; for p in "${pids[@]}"; do wait "$p" || fail=1; done
[[ "$fail" == "0" ]] || { echo "[$COMBO] a cell FAILED — see $LOGDIR"; exit 1; }
echo "[$COMBO] all cells done."
